query : Term Γ [modelDim]
values : Term Γ [sources, modelDim]
⊢ Term.eval env
      (have unitScale := Term.op (PrimOp.one [modelDim]) Args.nil;
      have normalized :=
        Term.op (PrimOp.rmsNorm [sources] modelDim hModel) (Args.cons values (Args.cons unitScale Args.nil));
      have transposed := Term.op (PrimOp.swapAdjacentAtDepth [sources, modelDim] 0) (Args.cons normalized Args.nil);
      have scores :=
        Term.op (PrimOp.broadcastVecMat [] [] [] modelDim sources term._proof_1 term._proof_1)
          (Args.cons query (Args.cons transposed Args.nil));
      have kernels := Term.op (PrimOp.exp [sources]) (Args.cons scores Args.nil);
      kernels.let1
        (have boundKernels := Term.var (Var.last Γ);
        have denominator := Term.op (PrimOp.sum [sources]) (Args.cons boundKernels Args.nil);
        have inverse := Term.op (PrimOp.inv []) (Args.cons denominator Args.nil);
        have weights := scaleTerm [sources] inverse boundKernels;
        Term.op (PrimOp.broadcastVecMat [] [] [] sources modelDim term._proof_1 term._proof_1)
          (Args.cons weights (Args.cons values.weakenRight Args.nil)))) =
    AttnRes.attendPacked hModel (Term.eval env query) (Term.eval env values)

