HeuristicEstimation.Sketch.gram_entry {α : Type} [Storage α] [CommSemiring α] {contexts d : ℕ}
  (weights : Tensor α [contexts]) (tails : Tensor α [contexts, d]) (i j : Fin d) :
  (gram weights tails)[(i, j)] = ∑ c, weights.getScalar c * tails[(c, i)] * tails[(c, j)]

HeuristicEstimation.Sketch.error_eq_quadratic {α : Type} [Storage α] [CommSemiring α] {contexts d : ℕ}
  (weights : Tensor α [contexts]) (tails : Tensor α [contexts, d]) (residual : Tensor α [d]) :
  error weights tails residual = quadratic (gram weights tails) residual

HeuristicEstimation.Sketch.gram_symmetric {α : Type} [Storage α] [CommSemiring α] {contexts d : ℕ}
  (weights : Tensor α [contexts]) (tails : Tensor α [contexts, d]) (i j : Fin d) :
  (gram weights tails)[(i, j)] = (gram weights tails)[(j, i)]
